#!/usr/bin/env python3
"""Bench autoclean dedup scope + archive step on a tiny fixture. Mirrors the jdupes calls used in /workspace/ops/autoclean.sh."""
import sys,os,json,shutil; sys.path.insert(0,os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import *
gitenv(); D="/tmp/git72-disk"; shutil.rmtree(D,True); os.makedirs(D)
def real(p): return int(sh(f"du -sB1 {p}").split()[0])  # counts hardlinks once
def fixture():
    shutil.rmtree(f"{D}/fx",True); make_site(f"{D}/fx/r1",20)
    sh(f"git -C {D}/fx/r1 repack -q -d"); # mixed: a pack + new loose objects
    open(f"{D}/fx/r1/extra.md","w").write("x"*4000); sh("git add -A && git commit -qm extra",f"{D}/fx/r1")
    for i in (2,3): sh(f"cp -a {D}/fx/r1 {D}/fx/r{i}")   # independent copies (like separate network clones)
    return real(f"{D}/fx")
r={}
b=fixture(); sh(f"jdupes -L -q {D}/fx/r*/.git/objects/pack || true"); r["old_packs_only"]={"before":b,"after":real(f"{D}/fx")}
b=fixture(); sh(f"hardlink -q -f {D}/fx/r*/.git/objects || true"); r["new_hardlink_objects"]={"before":b,"after":real(f"{D}/fx")}
for k in r: r[k]["saved"]=r[k]["before"]-r[k]["after"]
ok=all(sh(f"git -C {D}/fx/r{i} fsck --no-progress 2>&1; echo $?").strip().endswith("0") for i in (1,2,3)); r["fsck_ok_after_new"]=ok
# archive step (unchanged): tar vs zstd -19 --long=27
os.makedirs(f"{D}/w"); make_site(f"{D}/w/site",20); shutil.rmtree(f"{D}/w/site/.git")
sh(f"tar -C {D}/w -cf {D}/a.tar site && zstd -q -19 --long=27 {D}/a.tar -o {D}/a.tar.zst")
r["archive"]={"dir_bytes":real(f"{D}/w"),"tar":du(f"{D}/a.tar"),"tar_zst19":du(f"{D}/a.tar.zst")}
shutil.rmtree(D); print(json.dumps(r))

#!/usr/bin/env python3
import sys,os,json,shutil; sys.path.insert(0,os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import *
gitenv(); S="/tmp/git72-site"; O="/tmp/git72-out"; P=20
make_site(S,P); shutil.rmtree(O,ignore_errors=True); os.makedirs(O)
sh(f"tar --exclude=.git -cf {O}/site.tar -C {S} ."); sh(f"git bundle create -q {O}/site.bundle --all",S)
sh(f"zstd -q -19 {O}/site.bundle -o {O}/site.bundle.zst")
sz={k:du(f"{O}/{k}") for k in ["site.tar","site.bundle","site.bundle.zst"]}
def untar(): shutil.rmtree(f"{O}/a",True); os.makedirs(f"{O}/a"); sh(f"tar -xf {O}/site.tar -C {O}/a")
def clone(): shutil.rmtree(f"{O}/b",True); sh(f"git clone -q {O}/site.bundle {O}/b")
def zclone(): shutil.rmtree(f"{O}/c",True); sh(f"zstd -dqf {O}/site.bundle.zst -o {O}/u.bundle && git clone -q {O}/u.bundle {O}/c")
t={"site.tar":timed(untar),"site.bundle":timed(clone),"site.bundle.zst":timed(zclone)}
# incremental: 1 new page -> delta bundle fetched into existing clone
open(f"{S}/page20.md","w").write("# new\n"); sh("git add -A && git commit -qm new",S)
sh(f"git bundle create -q {O}/delta.bundle main ^HEAD~1",S)
dt=timed(lambda: sh(f"git fetch -q {O}/delta.bundle main:refs/remotes/usb/main",f"{O}/b"),3)
ok=sh(f"git -C {O}/b rev-parse refs/remotes/usb/main").strip()==sh("git rev-parse HEAD",S).strip()
r={"pages":P,"bytes":sz,"bytes_per_page":{k:round(v/P) for k,v in sz.items()},"sync_ms":t,
   "delta_bundle_bytes":du(f"{O}/delta.bundle"),"delta_fetch_ms":dt,"delta_ok":ok,"tokens":0}
shutil.rmtree(S); shutil.rmtree(O); print(json.dumps(r))

#!/usr/bin/env python3
import sys,os,json,shutil; sys.path.insert(0,os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import *
gitenv(); S="/tmp/git72-sp/src"; O="/tmp/git72-sp"; F="page07.md"
make_site(S,20); sh("git config uploadpack.allowFilter true && git config uploadpack.allowAnySHA1InWant true",S)
want=open(f"{S}/{F}").read(); res={}
def run(name,fn,land):
    ms=timed(lambda:(shutil.rmtree(land,True),fn()),5); ok=open(f"{land}/{F}").read()==want if os.path.isdir(land) else False
    res[name]={"ms":ms,"bytes_landed":du(land),"ok":ok,"tokens":0}
run("A_full_clone",lambda:sh(f"git clone -q file://{S} {O}/A"),f"{O}/A")
run("B_blobless_sparse",lambda:sh(f"git clone -q --filter=blob:none --no-checkout file://{S} {O}/B && git -C {O}/B sparse-checkout set --no-cone /{F} && git -C {O}/B checkout -q main"),f"{O}/B")
run("C_git_archive_path",lambda:(os.makedirs(f"{O}/C"),sh(f"git archive main {F} | tar -x -C {O}/C",S)),f"{O}/C")
run("C2_cat_file",lambda:(os.makedirs(f"{O}/C2"),sh(f"git -C {S} cat-file -p main:{F} > {O}/C2/{F}")),f"{O}/C2")
ms=timed(lambda:open(f"{S}/{F}").read(),5); res["D_cat_worktree"]={"ms":ms,"bytes_landed":0,"ok":True,"tokens":0}
shutil.rmtree(O); print(json.dumps(res))

